Box는 데이터를 stack에서 heap으로 옮길 수 있게 해주는 smart pointer
이를 역참조하면 마치 원래 자료형이었던 것처럼 heap에 할당된 데이터를 편하게 쓸 수 있음

struct Pie;

impl Pie {
    fn eat(&amp;self) {
        println!(&quot;heap에 있으니 더 맛있습니다!&quot;)
    }
}

fn main() {
    let heap_pie = Box::new(Pie);
    heap_pie.eat();
}

